/** Types used *before* and *after* model segmentation. No IDs are generated by the LLM. */
export type ExtractionMethod = "TEXT_LAYER" | "OCR";
export type ExtractionQuality = "GOOD" | "LOW" | "UNREADABLE";

export interface PdfPage {
  page_number: number;
  text: string;
  method: ExtractionMethod;
  quality: ExtractionQuality;
}

export interface SourceLine {
  id: number; // global line number (1-based) in reading order
  page: number;
  start_offset: number; // UTF-16 offset, inclusive, relative to this page's extracted text
  end_offset: number; // UTF-16 offset, exclusive, relative to this page's extracted text
  text: string;
}

export interface Locator {
  page_start: number;
  page_end: number;
  start_offset: number;
  end_offset: number;
  method: ExtractionMethod;
  quality: ExtractionQuality;
}

export interface Segment {
  number: string;
  title: string | null;
  start_line: number;
  heading_end_line: number;
  end_line: number;
}
export interface PointSegment extends Segment {}
export interface ClauseSegment extends Segment { points: PointSegment[] }
export interface ArticleSegment extends Segment { clauses: ClauseSegment[] }
export interface SectionSegment extends Segment { articles: ArticleSegment[] }
export interface ChapterSegment extends Segment { sections: SectionSegment[]; articles: ArticleSegment[] }
export interface PartSegment extends Segment {
  chapters: ChapterSegment[];
  sections: SectionSegment[];
  articles: ArticleSegment[];
}
export interface Segmentation {
  document_title: string;
  parts: PartSegment[];
  chapters: ChapterSegment[];
  sections: SectionSegment[];
  articles: ArticleSegment[];
}

export interface NodeBase {
  number: string;
  title: string | null;
  content: string | null;
  source_locator: Locator;
}
export interface Point extends NodeBase {}
export interface Clause extends NodeBase { points: Point[] }
export interface Article extends NodeBase { clauses: Clause[] }
export interface Section extends NodeBase { articles: Article[] }
export interface Chapter extends NodeBase { sections: Section[]; articles: Article[] }
export interface Part extends NodeBase {
  chapters: Chapter[];
  sections: Section[];
  articles: Article[];
}
export interface LegalDocument {
  document_title: string;
  content: string | null;
  source: { snapshot_id: string; pdf_sha256: string };
  parts: Part[];
  chapters: Chapter[];
  sections: Section[];
  articles: Article[];
}

/** Permanent review/unsupported PDF: do not repeatedly retry or persist a fake document. */
export class NeedsReviewError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "NeedsReviewError";
  }
}
